using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using TMPro;
public static partial class AtelierBuild {
 static void Wedge(Transform p,float width,float depth,float centre,float slope){
  float x=width/2,z=depth/2,h=Mathf.Tan(slope*Mathf.Deg2Rad)*z;
  Vector3[] points={V(-x,.055f,-z),V(x,.055f,-z),V(x,.055f,z),V(-x,.055f,z),V(-x,centre+h,-z),V(x,centre+h,-z),V(x,centre-h,z),V(-x,centre-h,z)};
  int[][] faces={new[]{0,3,2,1},new[]{4,5,6,7},new[]{0,1,5,4},new[]{1,2,6,5},new[]{2,3,7,6},new[]{3,0,4,7}};
  var vertices=new List<Vector3>();var uv=new List<Vector2>();var triangles=new List<int>();Vector3 middle=V(0,centre*.5f,0);
  foreach(var face in faces){int k=vertices.Count;var a=points[face[0]];var b=points[face[1]];var c=points[face[2]];bool reverse=Vector3.Dot(Vector3.Cross(b-a,c-a),(a+b+c)/3-middle)<0;foreach(int index in face){vertices.Add(points[index]);uv.Add(new Vector2(points[index].x,points[index].z));}if(reverse)triangles.AddRange(new[]{k,k+2,k+1,k,k+3,k+2});else triangles.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}
  var m=new Mesh();m.SetVertices(vertices);m.SetUVs(0,uv);m.SetTriangles(triangles,0);m.RecalculateNormals();MeshObject("Walnut sloping cabinet",p,SaveMesh(m,"DeskWedge_"+meshSerial++),darkwood);
 }
 static Transform LowDesk(string name,Transform stage,Vector3 at,float width,float depth,float slope){var root=Group(name,stage,at);float centre=.45f;Wedge(root,width,depth,centre,slope);for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Cylinder("Rubber contact foot",root,V(x*(width/2-.23f),0,z*(depth/2-.22f)),V(x*(width/2-.23f),.065f,z*(depth/2-.22f)),.13f,black,16);var deck=Group("Inclined work surface",root,V(0,centre,0));deck.localRotation=Quaternion.Euler(slope,0,0);Box("Rounded walnut rim",deck,Vector3.zero,V(width,.10f,depth),darkwood,.06f);Box("Fine brass reveal",deck,V(0,.056f,0),V(width-.16f,.018f,depth-.16f),brass,.035f);Box("Navy instrument panel",deck,V(0,.072f,0),V(width-.20f,.018f,depth-.20f),navy,.035f);for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Bolt(deck,V(x*(width/2-.18f),.09f,z*(depth/2-.18f)),Vector3.up,.025f);return deck;}
 static TMP_Text FlatLabel(Transform parent,string text,Vector3 at,float size,Color? color=null){var label=Label(parent,text,at,size,color);label.transform.localRotation=Quaternion.LookRotation(Vector3.down,Vector3.back);return label;}
 static TMP_Text Plaque(Transform parent,string text,Vector3 at,float width,float fontSize=.69f){Box("Engraved brass name plate",parent,at,V(width,.019f,.17f),brass,.015f);return FlatLabel(parent,text,at+Vector3.up*.013f,fontSize,new Color(.012f,.009f,.006f));}
 static AtelierControl Paddle(Transform parent,AtelierAction action,string caption,Vector3 at,float width){var root=Group(caption,parent,at);Box("Paddle recessed bezel",root,V(0,-.01f,0),V(width+.08f,.035f,.41f),black,.025f);Box("Brass thumb paddle",root,V(0,.025f,0),V(width,.05f,.34f),brass,.03f);FlatLabel(root,caption,V(0,.054f,0),1.02f,new Color(.012f,.009f,.006f));float sign=action==AtelierAction.TrayPrevious?1:-1;var arrow=new Mesh();arrow.vertices=new[]{V(sign*(width*.39f+.04f),.056f,0),V(sign*(width*.39f-.04f),.056f,-.065f),V(sign*(width*.39f-.04f),.056f,.065f)};arrow.triangles=sign>0?new[]{0,1,2}:new[]{0,2,1};arrow.RecalculateNormals();MeshObject("Cast navigation arrow",root,SaveMesh(arrow,"Arrow_"+meshSerial++),black);
  var control=root.gameObject.AddComponent<AtelierControl>();control.action=action;control.caption=caption+" · 点击";var hit=root.gameObject.AddComponent<BoxCollider>();hit.center=V(0,.035f,0);hit.size=V(width,.12f,.36f);return control;}
 static Transform QuadrantA(Transform parent,AtelierAction action,string caption,Vector3 at,Material grip,float height,bool tGrip){var root=Group(caption,parent,at);Box("Bolted quadrant shoe",root,V(0,.025f,0),V(.60f,.05f,.64f),black,.035f);for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2)Bolt(root,V(x*.24f,.056f,z*.25f),Vector3.up,.018f);Cylinder("Crosswise pivot journal",root,V(-.18f,.16f,0),V(.18f,.16f,0),.135f,brass,32);var pivot=Group("Moving handle",root,V(0,.16f,0));Cylinder("Machined operating arm",pivot,Vector3.zero,V(0,height,0),.04f,brass,16);if(tGrip){Cylinder("Horizontal insulated grip",pivot,V(-.23f,height,0),V(.23f,height,0),.08f,grip,24);for(int side=-1;side<=1;side+=2)Cylinder("Brass grip end",pivot,V(side*.23f,height,0),V(side*.255f,height,0),.082f,brass,24);}else{Cylinder("Insulated brake grip",pivot,V(0,height-.17f,0),V(0,height+.08f,0),.065f,grip,24);}
  var control=pivot.gameObject.AddComponent<AtelierControl>();control.action=action;control.caption=caption;control.pivot=pivot;var col=pivot.gameObject.AddComponent<BoxCollider>();col.center=V(0,height/2,0);col.size=V(tGrip?.55f:.28f,height+.20f,.24f);
  for(int side=-1;side<=1;side+=2){var arc=new List<Vector3>();for(int i=0;i<=24;i++){float a=(-42+i*3.5f)*Mathf.Deg2Rad;arc.Add(V(side*.23f,.16f+Mathf.Cos(a)*.26f,Mathf.Sin(a)*.26f));}Tube("Quadrant curved cheek",root,arc.ToArray(),.025f,brass,10);}return pivot;
 }
 static Transform ToggleA(Transform p,AtelierAction action,string caption,Vector3 at){var root=Group(caption,p,at);Cylinder("Toggle seat",root,Vector3.zero,V(0,.05f,0),.12f,black,24);Cylinder("Knurled mounting nut",root,V(0,.05f,0),V(0,.09f,0),.09f,brass,12);var pivot=Group("Toggle spindle",root,V(0,.09f,0));Cylinder("Toggle stem",pivot,Vector3.zero,V(0,.22f,0),.027f,steel,16);Cylinder("Toggle tip",pivot,V(0,.18f,0),V(0,.25f,0),.037f,brass,16);var c=root.gameObject.AddComponent<AtelierControl>();c.action=action;c.caption=caption+" · 点击切换";var hit=root.gameObject.AddComponent<BoxCollider>();hit.center=V(0,.16f,0);hit.size=V(.28f,.38f,.32f);return pivot;}
