  var tray=LowDesk("A · Low parts instrument tray",stage,V(5.25f,-.47f,3.55f),5.80f,3.45f,9);experience.trayRoot=tray;experience.traySlots=new Transform[8];experience.trayLabels=new TMP_Text[8];experience.trayOutlines=new GameObject[8];
