  experience.categoryLabels=new TMP_Text[4];string[] categories={"全部","轮组","传动","车体"};for(int i=0;i<4;i++){var root=Group("Category "+i,tray,U(-1.55f+i*.86f,.32f,-1.40f));experience.categoryLabels[i]=FlatLabel(root,categories[i],U(0,.01f,0),.77f);var c=root.gameObject.AddComponent<AtelierControl>();c.action=AtelierAction.Category;c.index=i+1;c.caption="显示"+categories[i]+"零件";var col=root.gameObject.AddComponent<BoxCollider>();col.center=U(0,.03f,0);col.size=V(.74f,.10f,.28f);}
  BuildPrecisionConsole(stage);
